function parseEmail(s){
  s=(s||'').trim();
  if(!s) return {valid:false,local:'',domain:'',tld:'',errors:['空输入']};
  var errors=[];
  var at=s.indexOf('@');
  if(at<1){ errors.push('缺少 @ 或 @ 前为空'); return {valid:false,local:'',domain:'',tld:'',errors:errors}; }
  if(at!==s.lastIndexOf('@')) errors.push('存在多个 @');
  var local=s.slice(0,at), domain=s.slice(at+1);
  if(!domain){ errors.push('@ 后域名为空'); }
  if(local.length>64) errors.push('局部超长(>64)');
  if(!/^[A-Za-z0-9._%+\-]+$/.test(local)) errors.push('局部含非法字符');
  if(domain){
    if(domain.startsWith('.')) errors.push('域名以 . 开头');
    if(domain.endsWith('.')) errors.push('域名以 . 结尾');
    if(domain.indexOf('..')>=0) errors.push('域名含连续点');
    var labels=domain.split('.');
    var tld=labels[labels.length-1];
    if(!/^[A-Za-z]{2,}$/.test(tld)) errors.push('TLD 非法(应 ≥2 字母)');
    for(var i=0;i<labels.length;i++){
      var L=labels[i];
      if(!/^[A-Za-z0-9\-]+$/.test(L)) errors.push('域名标签非法: '+L);
      if(L.startsWith('-')||L.endsWith('-')) errors.push('域名标签以 - 开头/结尾: '+L);
    }
  }
  return {valid:errors.length===0, local:local, domain:domain, tld:domain?domain.split('.').pop():'', errors:errors};
}

var EXPORTS={parseEmail:parseEmail};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EmailForgePure = EXPORTS; }
